    'rec.item_cat_008_desc': 'Point-to-point same-day dedicated hot-shot van delivery with real-time GPS telemetry.',
    'rec.item_cat_009_name': 'Certified Dock Inspection & Pre-Arrival Verification Service',
    'rec.item_cat_009_desc': 'On-dock third-party quality control and piece-by-piece barcode reconciliation.',
    'rec.item_cat_010_name': 'Real-Time BLE Temperature & Shock Data Logger',
    'rec.item_cat_010_desc': 'Bluetooth multi-use sensor logging temperature spikes and transit impact shocks.',
    'rec.reason_co_occurrence': 'High Co-Occurrence with {skus}',
    'rec.explain_co_occurrence': '87% of shippers dispatching {skus} also include this item to prevent transit damage or optimize load fill.',
    'rec.reason_browsing': 'Matches Recent Manifest Browsing & Category Affinity',
    'rec.explain_browsing': 'Recommended based on your recent inspection of {category} manifests and active route requirements.',
    'rec.reason_default': 'Aligned with Stated Operational Preferences',
    'rec.explain_default': 'Matches your selected {category} focus and {temp} handling profile.',
    'rec.roadmap_1_tier': 'Near-Term (Phase 2)',
    'rec.roadmap_1_title': 'Matrix Factorization & Implicit Feedback Embeddings',
    'rec.roadmap_1_desc': 'Transition from heuristic co-occurrence matrices to Alternating Least Squares (ALS) and Bayesian Personalized Ranking (BPR) over implicit signals (manifest views, dwell time, and dock discrepancy rates).',
    'rec.roadmap_1_rationale': 'Captures latent cross-category relationships even when two SKUs have never been explicitly dispatched together by the same sender.',
    'rec.roadmap_1_impl': 'Train nightly user/item latent vectors (d=64) in Python/Spark and serve low-latency cosine similarity lookups via pgvector in PostgreSQL.',
    'rec.roadmap_2_tier': 'Mid-Term (Phase 3)',
    'rec.roadmap_2_title': 'Two-Tower Deep Neural Retrieval & Context Ranking',
    'rec.roadmap_2_desc': 'Implement a Two-Tower neural architecture encoding User/Business context (role, historical loss rate, route distance, weather) and Item/Service features into a shared embedding space.',
    'rec.roadmap_2_rationale': 'Dynamically adapts recommendations in real time based on transit conditions (e.g., boosting thermal blankets during summer heatwaves or shock dividers on high-damage routes).',
    'rec.roadmap_2_impl': 'Sub-20ms candidate generation via Approximate Nearest Neighbor (ANN / HNSW) index followed by a LightGBM cross-feature reranker.',
    'rec.roadmap_3_tier': 'Long-Term (Phase 4)',
    'rec.roadmap_3_title': 'Supply-Chain Knowledge Graph & GNN Loss-Prevention Engine',
    'rec.roadmap_3_desc': 'Model shippers, carriers, origin docks, receiving partners, and SKUs as a heterogeneous graph trained with Graph Neural Networks (GraphSAGE).',
    'rec.roadmap_3_rationale': 'Predicts discrepancy probability before dispatch leaves the dock and automatically recommends protective packaging or audited carrier upgrades.',
    'rec.roadmap_3_impl': 'Event-driven streaming pipeline (Kafka + Flink) updating node embeddings upon every dock sign-off and discrepancy resolution.',
    'rec.roadmap_4_tier': 'Continuous Optimization',
    'rec.roadmap_4_title': 'Contextual Multi-Armed Bandits (Explore / Exploit)',
    'rec.roadmap_4_desc': 'Balance high-confidence catalog staples with newly onboarded logistics services and packaging innovations using Thompson Sampling.',
    'rec.roadmap_4_rationale': 'Prevents feedback loops and cold-start starvation for new SKUs while maintaining high conversion on proven recommendations.',
    'rec.roadmap_4_impl': 'Online bandit policy updated via real-time add-to-manifest and damage-reduction reward signals.',

