    'rec.explain_default': 'Xiyyeeffannoo {category} fi haala qabiinsa {temp} filattan waliin walsima.',
    'rec.roadmap_1_tier': 'Yeroo Dhihoo (Marsaa 2)',
    'rec.roadmap_1_title': 'Matrix Factorization fi Mallattoolee Yaada Kallattii Hin Taane',
    'rec.roadmap_1_desc': 'Maatriiksii waliin-argama irraa gara Alternating Least Squares (ALS) fi Bayesian Personalized Ranking (BPR) ilaalcha maanifeestii fi hir\'ina dookkii irratti hundaa\'etti ce\'uu.',
    'rec.roadmap_1_rationale': 'Hariiroo dhokataa ramaddiiwwan gidduu jiru qabata yoo meeshaaleen lama ergaa tokkoon waliin ergamanii hin beekne illee.',
    'rec.roadmap_1_impl': 'Veektaroota fayyadamaa/meeshaa (d=64) halkan halkan Python/Spark keessatti leenjisuu fi pgvector PostgreSQL keessatti dhiyeessuu.',
    'rec.roadmap_2_tier': 'Yeroo Giddu-galeessaa (Marsaa 3)',
    'rec.roadmap_2_title': 'Two-Tower Deep Neural Retrieval fi Sadarkeessa Haalaa',
    'rec.roadmap_2_desc': 'Ijaarsa niwuraalii Two-Tower haala Fayyadamaa/Daldalaa (gahee, hir\'ina seenaa, fageenya daandii, qilleensa) fi amala meeshaa walitti fidu.',
    'rec.roadmap_2_rationale': 'Haala imalaa irratti hundaa\'uun gorsa yeroo dhugaa keessatti sirreessa (fkn yeroo ho\'aa uffata qabbanaa dursa kennuu).',
    'rec.roadmap_2_impl': 'Kaadhimamtoota ms 20 gadiitti ANN / HNSW index fayyadamuun maddisiisuu fi LightGBM dhaan sadarkeessuu.',
    'rec.roadmap_3_tier': 'Yeroo Dheeraa (Marsaa 4)',
    'rec.roadmap_3_title': 'Giraafii Beekumsa Sansalata Dhiyeessii fi Moottora Ittisa Hir\'inaa GNN',
    'rec.roadmap_3_desc': 'Ergitoota, geejjibsitoota, dookkii ka\'umsaa, michoota fudhatootaa fi meeshaalee akka giraafii GraphSAGE leenjifameetti bocuu.',
    'rec.roadmap_3_rationale': 'Carraa hir\'inaa osoo ergaan dookkii hin bahin tilmaamuun saamsituu eegumsaa ykn geejjiba odiitii ta\'e ofumaan gorsa.',
    'rec.roadmap_3_impl': 'Ujummoo yaa\'insa yeroo dhugaa (Kafka + Flink) mallattoo dookkii fi furmaata falmii hunda irratti haaromsu.',
    'rec.roadmap_4_tier': 'Fooyya\'iinsa Walitti Fufaa',
    'rec.roadmap_4_title': 'Contextual Multi-Armed Bandits (Sakatta\'uu / Fayyadamuu)',
    'rec.roadmap_4_desc': 'Meeshaalee amantaa olaanaa qaban tajaajila loojistiksii haaraa waliin Thompson Sampling fayyadamuun madaaluu.',
    'rec.roadmap_4_rationale': 'Meeshaalee haaraaf rakkoo jalqabaa hambisuun gorsa mirkanaa\'e irratti bu\'aa olaanaa eega.',
    'rec.roadmap_4_impl': 'Imaammata toora irraa mallattoo badhaasa maanifeestiitti dabaluu fi hir\'ina miidhaatiin haaromfamu.',

