    'rec.reason_co_occurrence': 'Isku-imaansho Sare oo lala leeyahay {skus}',
    'rec.explain_co_occurrence': '87% rarayaasha dira {skus} waxay sidoo kale ku daraan shaygan si looga hortago dhaawaca safarka ama loo buuxiyo rarka.',
    'rec.reason_browsing': 'Wuxuu La Mid Yahay Baaritaanka Liiska Dhawaa & Xiriirka Qaybta',
    'rec.explain_browsing': 'Waxaa lagu taliyay iyadoo lagu saleynayo kormeerkaagii dhawaa ee liisaska {category} iyo shuruudaha waddada.',
    'rec.reason_default': 'La Jaangooyay Doorbidyada Hawlgalka ee La Sheegay',
    'rec.explain_default': 'Wuxuu la mid yahay diiraddaada {category} ee la doortay iyo qaabka maaraynta {temp}.',
    'rec.roadmap_1_tier': 'Muddo-Gaaban (Wejiga 2)',
    'rec.roadmap_1_title': 'Matrix Factorization & Calaamadaha Jawaab-celinta Dadban',
    'rec.roadmap_1_desc': 'U-gudbidda isku-imaanshaha fudud ilaa Alternating Least Squares (ALS) iyo Bayesian Personalized Ranking (BPR) ee calaamadaha dadban (eegista liiska iyo heerka khilaafaadka dekadda).',
    'rec.roadmap_1_rationale': 'Wuxuu qabtaa xiriirka qarsoon ee qaybaha xitaa marka laba shay aan weligood si wada-jir ah loogu dirin isla diraha.',
    'rec.roadmap_1_impl': 'Tababar habeennimo ah oo loo sameeyo vectors-ka isticmaalaha/shayga (d=64) ee Python/Spark iyo raadinta degdegga ah ee pgvector PostgreSQL.',
    'rec.roadmap_2_tier': 'Muddo-Dhexe (Wejiga 3)',
    'rec.roadmap_2_title': 'Two-Tower Deep Neural Retrieval & Qiimeynta Macnaha Guud',
    'rec.roadmap_2_desc': 'Hirgelinta qaab-dhismeedka neural-ka Two-Tower oo xिरिiriya macnaha Isticmaalaha/Ganacsiga (doorka, khasaaraha taariikhiga ah, masaafada, cimilada) iyo astaamaha Shayga.',
    'rec.roadmap_2_rationale': 'Si toos ah ayuu ula qabsadaa talooyinka waqtiga dhabta ah iyadoo lagu saleynayo xaaladaha safarka (tusaale, kor u qaadista bustayaasha kulaylka xilliga xagaaga).',
    'rec.roadmap_2_impl': 'Soo-saarista musharaxiinta ka yar 20ms iyadoo la adeegsanayo ANN / HNSW index oo ay ku xigto LightGBM reranker.',
    'rec.roadmap_3_tier': 'Muddo-Dheer (Wejiga 4)',
    'rec.roadmap_3_title': 'Shabakadda Aqoonta Silsiladda-Sahayda & Matoorka Kahortagga Khasaaraha GNN',
    'rec.roadmap_3_desc': 'Qaabaynta rarayaasha, gaadiidleyda, dekadaha asalka ah, lamaanayaasha qaabilaadda, iyo SKU-yada sida shabakad lagu tababaray Graph Neural Networks (GraphSAGE).',
    'rec.roadmap_3_rationale': 'Wuxuu saadaaliyaa suurtogalnimada khilaafka ka hor inta uusan shixnaddu ka bixin dekadda wuxuuna si toos ah ugu taliyaa baakadaha difaaca.',
    'rec.roadmap_3_impl': 'Tuubbada qulqulka dhacdooyinka (Kafka + Flink) oo cusboonaysiinaysa calaamadaha saxiix kasta oo dekadda ah.',
    'rec.roadmap_4_tier': 'Horumarin Joogto ah',
    'rec.roadmap_4_title': 'Contextual Multi-Armed Bandits (Baadhitaan / Ka-faa\'iidaysi)',
    'rec.roadmap_4_desc': 'Isku-dheelitirka alaabta kalsoonida sare leh iyo adeegyada cusub ee saadka iyadoo la adeegsanayo Thompson Sampling.',
    'rec.roadmap_4_rationale': 'Wuxuu ka hortagaa gaajada bilowga qabow ee alaabta cusub isagoo ilaalinaya wax-soo-saarka sare ee talooyinka la xaqiijiyay.',
    'rec.roadmap_4_impl': 'Siyaasadda tooska ah ee lagu cusboonaysiiyo ku-darista liiska waqtiga dhabta ah iyo calaamadaha abaalmarinta dhimista dhaawaca.',

